/**
 * Every live issue of a project, numbered order, walking all pages — a clone
 * copies the whole project, not the first page of it.
 */
export async function listAllLiveIssues(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const all: Issue[] = [];
  let cursor: string | null = null;

  do {
    const page: Page<Issue> = await listIssues({
      orgId,
      projectId,
      limit: 100,
      cursor,
    });
    all.push(...page.items);
    cursor = page.nextCursor;
  } while (cursor !== null);

  return all.sort((a, b) => a.number - b.number);
}

/**
 * Writes the copies of a clone's issues in one transaction. A copy keeps the
 * content of its source and nothing that records progress: it starts in the
 * default status, unassigned, unlinked, authored by `authorId`, and is
 * numbered 1..n in the order given. Comments and attachments are not copied.
 */
export function insertIssueCopies(
  orgId: OrgId,
  projectId: ProjectId,
  authorId: UserId,
  sources: readonly Issue[],
): number {
  const stamp = toIsoTimestamp(new Date());

  getDb().transaction((tx) => {
    sources.forEach((source, index) => {
      const row = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId,
          projectId,
          number: index + 1,
          title: source.title,
          description: source.description,
          status: "backlog",
          priority: source.priority,
          authorId,
          assigneeId: null,
          parentId: null,
          estimate: source.estimate,
          dueAt: source.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning({ id: issues.id })
        .get();

      if (source.labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            source.labelIds.map((labelId) => ({
              orgId,
              issueId: row.id,
              labelId,
            })),
          )
          .run();
      }
    });
  });

  return sources.length;
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */

