/**
 * Clones a live project into a new project of the same workspace (ADR 0012).
 * The gates are those of a creation plus a read of the source; the quotas are
 * checked for the whole batch before anything is written. Description,
 * visibility, colour and lead come from the source; the status, dates and
 * issue state do not. Search, usage and the audit log follow from the single
 * `project.cloned` event.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));
  assertNotArchived("Project", source.id, source);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const sources = input.includeIssues
    ? await issueRepo.listAllLiveIssues(input.orgId, source.id)
    : [];

  if (wouldExceedLimit(org.plan, "issuesPerProject", 0, sources.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more than ${getLimit(org.plan, "issuesPerProject")} issues in project ${input.key}; the source has ${sources.length}`,
    );
  }

  const project = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug: input.slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const issuesCopied = issueRepo.insertIssueCopies(
    input.orgId,
    project.id,
    actor.userId,
    sources,
  );

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied,
  });

  return project;
}

